import numpy as np

def read_vasp(filename):
    with open(filename, 'r') as f:
        lines = f.readlines()
    coordinates = []
    for line in lines[9:87]:
        if line.strip() == '':
            break
        split_line = line.split()
        coordinates.append([float(x) for x in split_line[:3]] + split_line[3:])
    return coordinates

def read_txt(filename):
    with open(filename, 'r') as f:
        lines = f.readlines()
    coordinates = []
    for line in lines[0:]:
        if line.strip() == '':
            continue
        coordinates.append([float(line.split()[2]), float(line.split()[3]), float(line.split()[4])])
    return coordinates

def write_vasp(filename, h_lines, coordinates):
    with open(filename, 'w') as f:
        f.write(h_lines)
        for coord in coordinates:
            f.write(f"{coord[0]: .10f} {coord[1]: .10f} {coord[2]: .10f}  {coord[3]}  {coord[4]}  {coord[5]}\n")

def convert_coords(coord2, x, y, z):
    divisors = [x, y, z]
    new_coord = [coord2[j] / divisors[j] for j in range(3)]
    return new_coord

def main(file1, file2, out1, x, y, z):
    with open(file1, 'r') as f1:
        h_lines_file1 = "".join(f1.readlines()[:9])

    coord1 = read_vasp(file1)
    coord2 = read_txt(file2)
    converted_coords = [convert_coords(coord, x, y, z) for coord in coord2]

    # Combine the converted coordinates with the T/F columns from coord1
    final_coords = [converted_coords[i] + coord1[i][3:] for i in range(len(converted_coords))]

    write_vasp(out1, h_lines_file1, final_coords)

if __name__ == "__main__":
    file1 = "AuTiO2.1.0.vasp"
    file2 = "fap.txt"
    out1  = "d3.1.0.vasp"
    x     = 10.4349002838
    y     = 7.5847997665
    z     = 28.8263830014866
    main(file1, file2, out1, x, y, z)
